<?php require_once 'functions.php';$pageTitle='Beranda';$q=trim($_GET['q']??'');$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();if($q){$s=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.name LIKE ? OR p.description LIKE ? ORDER BY p.created_at DESC');$s->execute(["%$q%","%$q%"]);$products=$s->fetchAll();}else{$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.stock>0 ORDER BY p.created_at DESC LIMIT 12')->fetchAll();}$recommended=recommend_products($pdo,null,4);require 'header.php';?><style>.product-seller-byline{display:block;color:#876d53;font-size:11px;margin:3px 0 7px;line-height:1.4}</style>
<section class="hero"><div><span class="eyebrow">KARYA LOKAL, CERITA ISTIMEWA</span><h1>Temukan karya unik,<br><em>dibuat dengan hati.</em></h1><p>Jelajahi produk handmade dari berbagai kreativitas pengrajin dan UMKM Indonesia.</p><a class="btn" href="#produk">Jelajahi Produk <b>→</b></a></div><div class="hero-art"><div class="art-circle">✿</div><div class="art-note">Handmade<br><b>with love</b></div><div class="art-stamp">LOCAL<br>CREATION</div></div></section>
<section id="kategori" class="section"><div class="section-head"><div><span class="eyebrow">JELAJAHI KREATIVITAS</span><h2>Kategori pilihan</h2></div></div><div class="category-grid"><?php foreach($cats as $c):
$categoryImages = ['Aksesori Handmade'=>'aksesori-handmade.jpg','Kerajinan Kayu'=>'kerajinan-kayu.jpg','Kerajinan Tekstil'=>'kerajinan-tekstil.jpg','Keramik & Gerabah'=>'keramik-gerabah.jpg','Lilin & Sabun'=>'lilin-sabun.jpg'];
$categoryImage = $categoryImages[$c['name']] ?? '';
?><a class="category" href="<?=url('category.php?id='.$c['id'])?>"><?php if($categoryImage && file_exists(__DIR__.'/uploads/products/'.$categoryImage)):?><img src="<?=url('uploads/products/'.$categoryImage)?>" alt="<?=e($c['name'])?>"><?php else:?><span>✳</span><?php endif;?><b><?=e($c['name'])?></b></a><?php endforeach;?></div></section>
<section class="section" id="produk"><div class="section-head"><div><span class="eyebrow">PILIHAN UNTUKMU</span><h2><?=$q?'Hasil pencarian':'Produk terbaru'?></h2></div><a class="text-link" href="<?=url('all-products.php')?>">Lihat semua →</a></div><div class="products"><?php foreach($products as $p):?><article class="product"><a href="<?=url('product.php?id='.$p['id'])?>"><img src="<?=e(image_url($p['image']))?>" alt="<?=e($p['name'])?>"></a><div class="product-info"><small><?=e($p['category_name']??'Handmade')?></small><a class="product-name" href="<?=url('product.php?id='.$p['id'])?>"><?=e($p['name'])?></a><small class="product-seller-byline">Dijual oleh <?=e(product_seller_label($pdo,(int)($p['seller_id']??0)))?></small><b><?=rupiah($p['price'])?></b><span class="stock">Stok <?=$p['stock']?></span></div></article><?php endforeach;?><?php if(!$products):?><p>Produk tidak ditemukan.</p><?php endif;?></div></section>
<section class="recommend"><div><span class="eyebrow">TEMUKAN INSPIRASI</span><h2>Rekomendasi produk</h2><p>Temukan karya lain yang mungkin sesuai dengan minatmu.</p></div><div class="mini-products"><?php foreach($recommended as $p):?><a href="<?=url('product.php?id='.$p['id'])?>"><img src="<?=e(image_url($p['image']))?>"><span><?=e($p['name'])?></span><b><?=rupiah($p['price'])?></b></a><?php endforeach;?></div></section><?php require 'footer.php';?>